#include <cstdio>
#include <cstring>
#include <string>
#include <algorithm>
#include <queue>
#include <cstdlib>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 199999999;

int grid[20][20];
int mat[MAXN][MAXN];
int n, N, T;
char s[200];
int hu[MAXN][3];
int re[MAXN][3];
int zr, zc;
int cx, cy;
int dir[4][2] = {{0,-1},{0,1},{-1,0},{1,0}};

int isok(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && grid[r][c] != -1)
        return (r-1)*n + c;
    return -1;
}

void BG() {
    N = n * n;
    memset(mat, -1, sizeof(mat));
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= n; ++c) {
            if (grid[r][c] == -1) continue;
            int p = (r-1)*n + c;
            mat[p][p] = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dir[d][0];
                int nc = c + dir[d][1];
                if (nr > 0 && nr <= n && nc > 0 && nc <= n && grid[nr][nc] != -1) {
                    int np = (nr-1)*n + nc;
                    mat[p][np] = 1;
                }
            }
        }
    }
}

int dis[MAXN];
int qu[MAXM];
int inq[MAXN];

void spfa() {
    int fr = 0, re = 1;
    for (int i = 1; i <= N; ++i) dis[i] = INF;
    int start = (zr-1)*n + zc;
    dis[start] = 0;
    qu[0] = start;
    while (fr < re) {
        int u = qu[fr++];
        for (int v = 1; v <= N; ++v) {
            if (mat[u][v] == 1 && dis[v] > dis[u] + 1) {
                dis[v] = dis[u] + 1;
                qu[re++] = v;
            }
        }
    }
}

void Floyd() {
    for (int k = 1; k <= N; ++k) {
        for (int i = 1; i <= N; ++i) {
            if (mat[i][k] == -1) continue;
            for (int j = 1; j <= N; ++j) {
                if (mat[k][j] == -1) continue;
                if (mat[i][j] == -1 || mat[i][j] > mat[i][k] + mat[k][j])
                    mat[i][j] = mat[i][k] + mat[k][j];
            }
        }
    }
}

struct Edge {
    int st, ed, flow, next;
} edge[MAXM];
int head[MAXN];
int E;
int src, dest;

void addedge(int st, int ed, int flow) {
    edge[E].st = st; edge[E].ed = ed; edge[E].flow = flow; edge[E].next = head[st];
    head[st] = E++;
    edge[E].st = ed; edge[E].ed = st; edge[E].flow = 0; edge[E].next = head[ed];
    head[ed] = E++;
}

void BF() {
    memset(head, -1, sizeof(head));
    E = 0;
    src = 0;
    dest = cx + cy + 1;
    for (int i = 1; i <= cx; ++i)
        addedge(src, i, hu[i][2]);
    for (int i = 1; i <= cy; ++i)
        addedge(cx + i, dest, re[i][2]);
    for (int i = 1; i <= cx; ++i) {
        for (int j = 1; j <= cy; ++j) {
            int p1 = (hu[i][0]-1)*n + hu[i][1];
            int p2 = (re[j][0]-1)*n + re[j][1];
            if (mat[p1][p2] != -1 && mat[p1][p2] <= T && mat[p1][p2] < dis[p2]) {
                addedge(i, cx + j, INF);
            } else if (mat[p1][p2] != -1 && mat[p1][p2] <= T && mat[p1][p2] == dis[p2]) {
                for (int d = 0; d < 4; ++d) {
                    int rr = re[j][0] + dir[d][0];
                    int cc = re[j][1] + dir[d][1];
                    int pp = isok(rr, cc);
                    if (pp != -1) {
                        if (mat[p1][pp] == mat[p1][p2] - 1 && mat[p1][pp] < dis[pp]) {
                            addedge(i, cx + j, INF);
                        }
                    }
                }
            }
        }
    }
}

int d[MAXN];
bool dinic_bfs() {
    int que[MAXN];
    int front = 0, rear = 1;
    que[0] = src;
    memset(d, -1, sizeof(d));
    d[src] = 0;
    while (front < rear) {
        int u = que[front++];
        for (int i = head[u]; i != -1; i = edge[i].next) {
            int v = edge[i].ed;
            if (d[v] == -1 && edge[i].flow > 0) {
                d[v] = d[u] + 1;
                if (v == dest) return true;
                que[rear++] = v;
            }
        }
    }
    return false;
}

int stk[MAXN];
int cur[MAXN];

int dinic() {
    int ret = 0;
    while (dinic_bfs()) {
        int u = src, tail = 0;
        for (int i = src; i <= dest; ++i) cur[i] = head[i];
        while (cur[src] != -1) {
            if (u != dest && cur[u] != -1 && edge[cur[u]].flow > 0 && d[u] != -1 && d[u] + 1 == d[edge[cur[u]].ed]) {
                stk[tail++] = cur[u];
                u = edge[cur[u]].ed;
            } else if (u == dest) {
                int minf = INF;
                for (int i = tail - 1; i >= 0; --i)
                    if (edge[stk[i]].flow < minf) minf = edge[stk[i]].flow;
                ret += minf;
                for (int i = tail - 1; i >= 0; --i) {
                    edge[stk[i]].flow -= minf;
                    edge[stk[i]^1].flow += minf;
                    if (edge[stk[i]].flow == 0) tail = i;
                }
                u = edge[stk[tail]].st;
            } else {
                while (tail > 0 && u != src && cur[u] == -1)
                    u = edge[stk[--tail]].st;
                cur[u] = edge[cur[u]].next;
            }
        }
    }
    return ret;
}

int solve() {
    grid[zr][zc] = 0;
    BG();
    spfa();
    grid[zr][zc] = -1;
    BG();
    Floyd();
    BF();
    return dinic();
}

int main() {
    scanf("%d%d", &n, &T);
    cx = cy = 0;
    memset(grid, 0, sizeof(grid));
    for (int i = 1; i <= n; ++i) {
        scanf("%s", s);
        for (int j = 0; j < n; ++j) {
            if (s[j] == 'Y') grid[i][j+1] = -1;
            else if (s[j] == 'Z') {
                zr = i; zc = j+1;
                grid[i][j+1] = -1;
            } else if (s[j] > '0' && s[j] <= '9') {
                hu[++cx][0] = i;
                hu[cx][1] = j+1;
                hu[cx][2] = s[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%s", s);
        for (int j = 0; j < n; ++j) {
            if (s[j] > '0' && s[j] <= '9') {
                re[++cy][0] = i;
                re[cy][1] = j+1;
                re[cy][2] = s[j] - '0';
            }
        }
    }
    printf("%d\n", solve());
    return 0;
}
